guard:
// Reject ambiguous nested repetition before compiling a backtracking RegExp.
// Fixed-width repetitions and the existing proven-safe rewrites remain unchanged.
if ((token.type === 'plus' || token.type === 'star') && !analysis.risky &&
    splitTopLevel(body).length === 1 &&
    tokens.slice(token.tokensIndex + 2).some(part =>
      part.type === 'star' || part.type === 'globstar' || part.type === 'plus' ||
      part.type === 'pipe' || part.type === 'comma' ||
      (part.type === 'paren' && part.value === '(') ||
      (part.type === 'brace' && part.value === '{'))) {
  throw new SyntaxError('Unsafe single-branch repeated extglob');
}
